PREFIX e: <https://example.invalid/ontology-browser/profile#>
PREFIX s: <https://example.invalid/ontology-browser/activity-sleep/>
PREFIX c: <http://connectdigitalstudy.com/ontology#>
PREFIX q: <http://qudt.org/schema/qudt/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
# The generic diary question asks for hours slept, with a numeric string answer.
# This question alone interprets that answer as hours and converts it to minutes.
# It does not create a Measurement, infer sensor equivalence or diagnose sleep.
SELECT ?participant ?night ?response ?reportedHours ?reportedMinutes ?estimate ?estimatedMinutes ?differenceMinutes WHERE {
  ?response a c:ResponseItem ; c:wasReportedBy ?participant ; e:night ?night ;
    c:answersQuestion s:diary-question ;
    e:answerUnit "hours" ; c:hasResponseValue ?reportedHours .
  BIND(xsd:decimal(?reportedHours) * 60 AS ?reportedMinutes)
  OPTIONAL {
    ?estimate e:quantityMeaning "estimated-sleep-duration" ; c:featureOfInterest ?participant ; e:night ?night .
    OPTIONAL { ?estimate q:quantityValue/q:numericValue ?estimatedMinutes }
  }
  BIND(?reportedMinutes - ?estimatedMinutes AS ?differenceMinutes)
} ORDER BY ?participant ?night

PREFIX s: <https://example.invalid/ontology-browser/activity-sleep/>
PREFIX raw: <https://example.invalid/ontology-browser/activity-sleep/raw#>
PREFIX e: <https://example.invalid/ontology-browser/profile#>
PREFIX c: <http://connectdigitalstudy.com/ontology#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX prov: <http://www.w3.org/ns/prov#>
CONSTRUCT {
  ?row e:semantic ?response .
  ?response a c:ResponseItem ; rdfs:label ?label ;
    rdfs:comment "Self-reported answer to the generic question: How many hours do you think you slept last night?" ;
    c:hasResponseValue ?answer ; c:wasReportedBy ?participant ; e:night ?night ;
    c:answersQuestion s:diary-question ;
    e:answerUnit "hours" ; e:source s:sleep-diary ; e:study s:study ;
    prov:wasDerivedFrom ?row ; e:note ?note .
} WHERE {
  ?row raw:table s:sleep-diary ; raw:respondent ?code ; raw:night_began ?night ; raw:hours_answer ?answer ; raw:output ?response .
  ?identity e:identityTable s:sleep-diary ; raw:code ?code ; e:participant ?participant .
  OPTIONAL { ?row raw:comment ?note }
  BIND(CONCAT("Diary response ", STRAFTER(STR(?response), "diary-response-")) AS ?label)
}

PREFIX e: <https://example.invalid/ontology-browser/profile#>
PREFIX c: <http://connectdigitalstudy.com/ontology#>
PREFIX q: <http://qudt.org/schema/qudt/>
PREFIX prov: <http://www.w3.org/ns/prov#>
SELECT ?participant ?day ?source ?grain ?record ?steps ?unit ?start ?end ?sourceRecord WHERE {
  ?record a c:StepCountMeasurement ; c:featureOfInterest ?participant ; e:day ?day ;
    e:source ?source ; e:grain ?grain ; e:unit ?unit ; prov:wasDerivedFrom ?sourceRecord .
  OPTIONAL { ?record q:quantityValue/q:numericValue ?steps }
  OPTIONAL { ?record e:start ?start ; e:end ?end }
} ORDER BY ?participant ?day ?source ?start ?record

PREFIX s: <https://example.invalid/ontology-browser/activity-sleep/>
PREFIX raw: <https://example.invalid/ontology-browser/activity-sleep/raw#>
PREFIX e: <https://example.invalid/ontology-browser/profile#>
PREFIX c: <http://connectdigitalstudy.com/ontology#>
PREFIX q: <http://qudt.org/schema/qudt/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX prov: <http://www.w3.org/ns/prov#>
CONSTRUCT {
  ?row e:semantic ?obs .
  ?obs a e:Observation, c:StepCountMeasurement ; rdfs:label ?label ;
    rdfs:comment "Step count over the stated half-open UTC interval." ;
    c:observedProperty c:StepCount ; c:featureOfInterest ?participant ;
    c:resultTime ?end ; e:start ?start ; e:end ?end ; e:day ?day ;
    e:grain "interval" ; e:quantityMeaning "steps" ; e:unit "steps" ;
    e:source s:stride-intervals ; e:study s:study ; prov:wasDerivedFrom ?row ; q:quantityValue ?quantity .
  ?quantity a q:QuantityValue ; q:numericValue ?count ; q:unit s:steps-unit .
} WHERE {
  ?row raw:table s:stride-intervals ; raw:person_code ?code ;
    raw:window_start ?start ; raw:window_end ?end ; raw:steps_in_window ?count ;
    raw:study_day ?day ; raw:output ?obs .
  ?identity e:identityTable s:stride-intervals ; raw:code ?code ; e:participant ?participant .
  BIND(IRI(CONCAT(STR(?obs), "-quantity")) AS ?quantity)
  BIND(CONCAT("Stride interval ", STRAFTER(STR(?obs), "stride-observation-")) AS ?label)
}

